    "what-state-am-i-in":{name:"In welke staat of regio ben ik?",short:"Vind de Amerikaanse staat of vergelijkbare eerste bestuurlijke laag wereldwijd.",intro:"Het punt wordt vergeleken met grenzen van administratieve eenheden op het eerste niveau.",quickAnswer:"Afhankelijk van het land kan dit een provincie, regio of vergelijkbare eenheid zijn.",howTo:["Selecteer je locatie.","Controleer staat of regio.","Test een ander punt."],faq:[["Wat doet deze tool?","Afhankelijk van het land kan dit een provincie, regio of vergelijkbare eenheid zijn."],["Is het resultaat altijd exact?","De nauwkeurigheid hangt af van de beschikbare kaart- en administratieve gegevens."]],longForm:{title:"In welke staat of regio ben ik?",paras:["Het punt wordt vergeleken met grenzen van administratieve eenheden op het eerste niveau.","Afhankelijk van het land kan dit een provincie, regio of vergelijkbare eenheid zijn."]}},
    "what-country-am-i-in":{name:"In welk land ben ik?",short:"Bepaal het land van je locatie of van een willekeurig punt op de kaart.",intro:"De tool gebruikt grenzen van OpenStreetMap en toont indien beschikbaar de ISO-code.",quickAnswer:"Zeegebieden en sommige betwiste grenzen kunnen afhangen van de gebruikte kaartgegevens.",howTo:["Sta locatie toe of klik op de kaart.","Controleer land en ISO-code.","Vergelijk punten nabij een grens."],faq:[["Wat doet deze tool?","Zeegebieden en sommige betwiste grenzen kunnen afhangen van de gebruikte kaartgegevens."],["Is het resultaat altijd exact?","De nauwkeurigheid hangt af van de beschikbare kaart- en administratieve gegevens."]],longForm:{title:"In welk land ben ik?",paras:["De tool gebruikt grenzen van OpenStreetMap en toont indien beschikbaar de ISO-code.","Zeegebieden en sommige betwiste grenzen kunnen afhangen van de gebruikte kaartgegevens."]}},
